LOGIN_ACCOUNT = #{loginAccount}, USER_NAME = #{userName}, MOBILE_PHONE = #{mobilePhone}, DEPT_NAME = #{deptName}, USER_TYPE = #{userType}, DESCRIPTION = #{description}, STATUS = #{status}, ERROR_MSG = #{errorMsg}, ORGAN_QZH = #{organQzh},
