INSERT INTO T_S_RP (ROLEID, PRIVILEGEID)
SELECT #{newRoleId}, PRIVILEGEID FROM T_S_RP
WHERE ROLEID = #{templateRoleId}
  AND PRIVILEGEID NOT IN ('C9612BA9318BFF034B6AF6C452A9FDF2', '8108DC96C90E27872FFEB06418A8C5A7', 'B07CB1BDCDA2C39AC2EF8E3CBE042F5B', '7A83D778858083A1AFA41072C468EC31')
  AND PRIVILEGEID NOT IN (
    SELECT PRIVILEGEID FROM T_S_PRIVILEGE
    WHERE PRODUCTID IN (
        SELECT PRODUCTID FROM T_S_PRODUCT WHERE NAME IN ('档案馆档案管理系统', '监督指导系统（档案局）', '档案利用平台')
    )
)
